(function () {
'use strict';
var form = document.getElementById('cinv-form');
if (!form) return;
var body = form.querySelector('[data-cinv-rows]');
var addBtn = form.querySelector('[data-cinv-add]');
var currencyField = form.querySelector('[data-cinv-currency]');
var taxField = form.querySelector('[data-cinv-tax]');
var WORDS = JSON.parse(form.getAttribute('data-currency-words') || '{}');
var DECIMALS = JSON.parse(form.getAttribute('data-decimals') || '{}');
var MAX = parseInt(form.getAttribute('data-max-lines') || '100', 10);
var cur = function () { return currencyField.value; };
var dec = function () { return DECIMALS[cur()] != null ? DECIMALS[cur()] : 2; };
var num = function (v) {
var n = parseFloat(String(v).replace(/[\s  ]/g, '').replace(',', '.'));
return isFinite(n) ? n : NaN;
};
var round = function (v, d) { var f = Math.pow(10, d); return Math.round(v * f) / f; };
var fmt = function (v) {
return new Intl.NumberFormat('fr-FR', { minimumFractionDigits: dec(), maximumFractionDigits: dec() }).format(v);
};
var label = function () { return cur() === 'XAF' ? 'FCFA' : cur(); };
var UNITS = ['zéro', 'un', 'deux', 'trois', 'quatre', 'cinq', 'six', 'sept', 'huit', 'neuf', 'dix',
'onze', 'douze', 'treize', 'quatorze', 'quinze', 'seize'];
var TENS = { 2: 'vingt', 3: 'trente', 4: 'quarante', 5: 'cinquante', 6: 'soixante' };
var below100 = function (n) {
if (n < 17) return UNITS[n];
if (n < 20) return 'dix-' + UNITS[n - 10];
var t = Math.floor(n / 10), u = n % 10;
if (t === 7 || t === 9) return t === 7 && u === 1 ? 'soixante et onze' : (t === 7 ? 'soixante' : 'quatre-vingt') + '-' + below100(10 + u);
if (t === 8) return u === 0 ? 'quatre-vingts' : 'quatre-vingt-' + UNITS[u];
return u === 0 ? TENS[t] : (u === 1 ? TENS[t] + ' et un' : TENS[t] + '-' + UNITS[u]);
};
var below1000 = function (n, final) {
var h = Math.floor(n / 100), r = n % 100, parts = [];
if (h === 1) parts.push('cent');
else if (h > 1) parts.push(below100(h) + (r === 0 && final ? ' cents' : ' cent'));
if (r > 0 || h === 0) parts.push(below100(r));
return parts.join(' ');
};
var words = function (n) {
if (n === 0) return 'zéro';
var out = [];
[[1e9, 'milliard'], [1e6, 'million']].forEach(function (p) {
var c = Math.floor(n / p[0]);
if (c > 0) { out.push(below1000(c, true) + ' ' + p[1] + (c > 1 ? 's' : '')); n %= p[0]; }
});
var th = Math.floor(n / 1000);
if (th > 0) { out.push(th === 1 ? 'mille' : below1000(th, false).replace(/(vingt|cent)s$/, '$1') + ' mille'); n %= 1000; }
if (n > 0) out.push(below1000(n, true));
return out.join(' ');
};
var amountWords = function (amount) {
var w = WORDS[cur()] || [cur(), cur()];
amount = round(Math.abs(amount), dec());
var whole = Math.floor(amount + 1e-9);
var cents = dec() > 0 ? Math.round((amount - whole) * 100) : 0;
if (whole > 999999999999) return '';
var text = words(whole);
var of = /(million|milliard)s?$/.test(text) ? (/^[aeiouyéè]/i.test(w[1]) ? " d'" : ' de ') : ' ';
text += of + (whole > 1 ? w[1] : w[0]);
if (cents > 0) text += ' et ' + words(cents) + ' centime' + (cents > 1 ? 's' : '');
return text.charAt(0).toUpperCase() + text.slice(1);
};
var rows = function () { return Array.prototype.slice.call(body.querySelectorAll('[data-cinv-row]')); };
var isEmpty = function (row) {
var q = row.querySelector('[data-cinv-qty]').value.trim();
return !row.querySelector('[data-cinv-desc]').value.trim() && (q === '' || q === '1') && !row.querySelector('[data-cinv-price]').value.trim();
};
var renumber = function () {
rows().forEach(function (row, i) {
row.querySelector('[data-cinv-n]').textContent = i + 1;
row.querySelector('[data-cinv-desc]').setAttribute('aria-label', 'Désignation, ligne ' + (i + 1));
row.querySelector('[data-cinv-qty]').setAttribute('aria-label', 'Quantité, ligne ' + (i + 1));
row.querySelector('[data-cinv-price]').setAttribute('aria-label', 'Prix unitaire, ligne ' + (i + 1));
});
};
var addRow = function (focus) {
if (rows().length >= MAX + 1) return null;
var tpl = rows()[0].cloneNode(true);
tpl.querySelectorAll('textarea, input').forEach(function (f) { f.value = ''; f.removeAttribute('aria-invalid'); });
tpl.querySelector('[data-cinv-line]').textContent = '—';
body.appendChild(tpl);
renumber();
autosize(tpl.querySelector('[data-cinv-desc]'));
if (focus) tpl.querySelector('[data-cinv-desc]').focus();
return tpl;
};
var ensureBlankRow = function () {
var all = rows();
if (!isEmpty(all[all.length - 1])) addRow(false);
};
var autosize = function (ta) {
ta.style.height = 'auto';
ta.style.height = Math.max(ta.scrollHeight, 34) + 'px';
};
var recalc = function () {
var subtotal = 0, d = dec();
rows().forEach(function (row) {
var out = row.querySelector('[data-cinv-line]');
if (isEmpty(row)) { out.textContent = '—'; return; }
var qRaw = row.querySelector('[data-cinv-qty]').value;
var q = qRaw.trim() === '' ? 1 : num(qRaw);
var p = num(row.querySelector('[data-cinv-price]').value || '0');
if (!(q > 0) || !(p >= 0)) { out.textContent = '?'; return; }
var line = round(q * round(p, d), d);
subtotal += line;
out.textContent = fmt(line);
});
subtotal = round(subtotal, d);
var rate = num(taxField.value || '0');
if (!(rate >= 0 && rate <= 100)) rate = 0;
var tax = round(subtotal * rate / 100, d);
var total = round(subtotal + tax, d);
form.querySelector('[data-cinv-subtotal]').textContent = fmt(subtotal) + ' ' + label();
form.querySelector('[data-cinv-taxamount]').textContent = fmt(tax) + ' ' + label();
form.querySelector('[data-cinv-total]').textContent = fmt(total) + ' ' + label();
form.querySelector('[data-cinv-words]').textContent = total > 0 ? amountWords(total) : '';
};
body.addEventListener('input', function (e) {
if (e.target.matches('[data-cinv-desc]')) autosize(e.target);
ensureBlankRow();
recalc();
});
body.addEventListener('click', function (e) {
var btn = e.target.closest('[data-cinv-remove]');
if (!btn) return;
var row = btn.closest('[data-cinv-row]');
if (rows().length > 1) row.remove();
else row.querySelectorAll('textarea, input').forEach(function (f) { f.value = ''; });
renumber();
ensureBlankRow();
recalc();
});
body.addEventListener('keydown', function (e) {
var field = e.target;
if (!field.matches('[data-cinv-desc], [data-cinv-qty], [data-cinv-price]')) return;
var row = field.closest('[data-cinv-row]');
var col = field.matches('[data-cinv-desc]') ? '[data-cinv-desc]' : (field.matches('[data-cinv-qty]') ? '[data-cinv-qty]' : '[data-cinv-price]');
var target = null;
if (e.key === 'Enter' && !e.shiftKey) {          // Maj + Entrée : retour à la ligne dans la désignation
e.preventDefault();
target = row.nextElementSibling || addRow(false);
} else if (e.key === 'ArrowDown' && (col !== '[data-cinv-desc]' || field.selectionStart === field.value.length)) {
target = row.nextElementSibling;
} else if (e.key === 'ArrowUp' && (col !== '[data-cinv-desc]' || field.selectionStart === 0)) {
target = row.previousElementSibling;
}
if (target) {
e.preventDefault();
var next = target.querySelector(col);
next.focus();
if (next.select) next.select();
}
});
taxField.addEventListener('input', recalc);
currencyField.addEventListener('change', recalc);
form.querySelectorAll('[data-cinv-tax-preset]').forEach(function (b) {
b.addEventListener('click', function () { taxField.value = b.getAttribute('data-cinv-tax-preset'); recalc(); });
});
if (addBtn) {
addBtn.hidden = false;
addBtn.addEventListener('click', function () { addRow(true); recalc(); });
}
var all = rows();
for (var i = all.length - 1; i > 0 && isEmpty(all[i]) && isEmpty(all[i - 1]); i--) all[i].remove();
renumber();
rows().forEach(function (r) { autosize(r.querySelector('[data-cinv-desc]')); });
ensureBlankRow();
recalc();
})();
